-- Model: lnk_hrrepresentative_customfieldshrrep__hr_representative_hkey_curr
-- Description: Current active relationship for LNK_HRREPRESENTATIVE_CUSTOMFIELDSHRREP using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_HRREPRESENTATIVE_CUSTOMFIELDSHRREP_HKEY AS LNK_HRREPRESENTATIVE_CUSTOMFIELDSHRREP_HKEY,
    l.HR_REPRESENTATIVE_HKEY AS HR_REPRESENTATIVE_HKEY,
    l.CUSTOMFIELDSHR_REP_HKEY AS CUSTOMFIELDSHR_REP_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.LOAD_DATE

    ROW_NUMBER() OVER (
        PARTITION BY l.HR_REPRESENTATIVE_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.LOAD_DATE
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_hrrepresentative_customfieldshrrep') }} l
INNER JOIN {{ ref('lks_erc_hrrepresentative_customfieldshrrep_curr') }} ls
    ON l.LNK_HRREPRESENTATIVE_CUSTOMFIELDSHRREP_HKEY = ls.LNK_HRREPRESENTATIVE_CUSTOMFIELDSHRREP_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
